type Mapping struct {
    data []byte
}

func NewMapping(fd int, size int) (*Mapping, error) {
    data, err := syscall.Mmap(fd, 0, size, syscall.PROT_READ, syscall.MAP_SHARED)
    if err != nil {
        return nil, err
    }
    m := &Mapping{data: data}
    runtime.AddCleanup(m, func(d []byte) { syscall.Munmap(d) }, data)  // страховка
    return m, nil
}

